n=19
g=[[0]*n for _ in range(n)]
centers={(3,6):8,(4,13):4,(12,14):1,(14,3):2}
marks=[(2,6),(4,6),(3,5),(3,7),(3,13),(5,13),(4,12),(4,14),(9,8),(11,8),(10,7),(10,9),(11,14),(13,14),(12,13),(12,15),(13,3),(15,3),(14,2),(14,4)]
for r,c in marks:g[r][c]=3
for (r,c),v in centers.items():g[r][c]=v
# horizontal lines; the empty cross column remains a gap
for (r,c),v in centers.items():
    for j in range(n):
        if j!=8 and g[r][j]!=3:g[r][j]=v
