print('\n'.join(' '.join(map(str,row)) for row in g))

n=19
g2=[[0]*n for _ in range(n)]
centers={(3,6):8,(4,13):4,(12,14):1,(14,3):2}
blank=(10,8)
# Record marker ownership by plus
shapes={pos:{(pos[0]-1,pos[1]),(pos[0]+1,pos[1]),(pos[0],pos[1]-1),(pos[0],pos[1]+1)} for pos in centers}
shapes[blank]={(blank[0]-1,blank[1]),(blank[0]+1,blank[1]),(blank[0],blank[1]-1),(blank[0],blank[1]+1)}
allmarks=set().union(*shapes.values())
for r,c in allmarks:g2[r][c]=3
for (r,c),v in centers.items():g2[r][c]=v
# Color horizontal rays, passing through own arms but stopping at another plus marker.
for (r,c),v in centers.items():
 for dc in (-1,1):
  j=c+dc
  while 0<=j<n:
   if (r,j) in shapes[(r,c)]:
    j+=dc; continue
   if (r,j) in allmarks or (r,j) in centers or (r,j)==blank:
    break
   g2[r][j]=v
   j+=dc
# The blank cross's vertical track is a zero line.
for i in range(n):
 if (i,blank[1]) not in allmarks and (i,blank[1]) not in centers:
  g2[i][blank[1]]=0
# Its horizontal track is blank too, then colored vertical rays overwrite it.
for j in range(n):
 if (blank[0],j) not in allmarks:
  g2[blank[0]][j]=0
# Color vertical rays; pass own arms; stop at other markers.
for (r,c),v in centers.items():
 for dr in (-1,1):
  i=r+dr
  while 0<=i<n:
   if (i,c) in shapes[(r,c)]:
    i+=dr; continue
   if (i,c) in allmarks or (i,c) in centers or (i,c)==blank:
    break
   g2[i][c]=v
   i+=dr
print('\n'.join(' '.join(map(str,row)) for row in g2))
